module top_module_tb;

    // Testbench signals (sequential circuit)
    reg RESET_L;
    reg [2:0] address;
    reg clk;
    reg [5:0] data;
    reg read;
    reg write;
    wire [5:0] data_out;
    wire err;
    wire valid_out;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

