        .read(read),
        .write(write),
        .data_out(data_out),
        .err(err),
        .valid_out(valid_out)
    );

    // Clock generation (10ns period)
    initial begin
        RESET_L = 0;
        forever #5 RESET_L = ~RESET_L;
    end

        task reset_dut;

        begin
            RESET_L = 0;
            address = 0;
            data = 0;
            write = 0;
            read = 0;
            repeat(2) @(posedge clk);
            #1;
            RESET_L = 1;
            @(posedge clk);
