            read = 0;
            @(posedge clk);
            #1;
            write = 0;


            address = 3'd3;
            read = 1;
            @(posedge clk);
            #1;


            #1;



            check_outputs(6'h2A, 1'b0, 1'b1);
            read = 0;
            @(posedge clk);
