            read = 1;
            write = 0;
            @(posedge clk);
            #1;


            #1;



            check_outputs(6'h00, 1'b0, 1'b1);
            read = 0;
            @(posedge clk);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Read/Write Conflict Error", test_num);
            reset_dut();


            address = 3'd0;
            data = 6'h11;
            write = 1;
            read = 1;
            @(posedge clk);
            #1;



            #1;




            check_outputs(data_out, 1'b1, valid_out);

            write = 0;
            read = 0;
            @(posedge clk);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Overwriting Data", test_num);
            reset_dut();


            address = 3'd2;
