            data = 6'h1F;
            write = 1;
            @(posedge clk);
            #1;
            write = 0;


            read = 1;
            @(posedge clk);
            #1;

            #1;


            check_outputs(6'h1F, 1'b0, 1'b1);
            read = 0;
            @(posedge clk);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Boundary Address (7)", test_num);
            reset_dut();


            address = 3'd7;
            data = 6'h33;
            write = 1;
            @(posedge clk);
            #1;
            write = 0;


            read = 1;
            @(posedge clk);
            #1;

            #1;


            check_outputs(6'h33, 1'b0, 1'b1);
            read = 0;
            @(posedge clk);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            $display("Test Case %03d: Error Recovery", test_num);
            reset_dut();


            write = 1; read = 1;
            @(posedge clk);
            #1;


            write = 1; read = 0;
            address = 3'd4; data = 6'h0A;
            @(posedge clk);
            #1;
            write = 0;


            read = 1;
            @(posedge clk);
            #1;


            #1;



            check_outputs(6'h0A, 1'b0, 1'b1);
            read = 0;
            @(posedge clk);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [5:0] expected_data_out;
        input expected_err;
        input expected_valid_out;
        begin
            if (expected_data_out === (expected_data_out ^ data_out ^ expected_data_out) &&
                expected_err === (expected_err ^ err ^ expected_err) &&
                expected_valid_out === (expected_valid_out ^ valid_out ^ expected_valid_out)) begin
                $display("PASS");
