                $display("  Got:      data_out=%h, err=%b, valid_out=%b",
                         data_out, err, valid_out);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,RESET_L, address, clk, data, read, write, data_out, err, valid_out);
    end

endmodule

