module binary_counter(CLK,RST,Q);
input CLK,RST;
output [3:0] Q;
reg [3:0] Q;

always@(posedge CLK or posedge RST) begin
    if (RST)
        Q <= 0;
    else
        Q <= Q + 1;
end

endmodule

