module top_module(
    input clk,
    input rst,
    input en,
    input ld,
    input [3:0] load_data,
    output reg [3:0] count
);reg [3:0] count_reg1, count_reg2;

always @(posedge clk) begin
    if (rst) begin
        count_reg1 <= 4'b0000;
        count_reg2 <= 4'b0000;
    end
    else if (en) begin
        count_reg1 <= count_reg2 + 4'b0001;
        count_reg2 <= count_reg1;
    end
    else if (ld) begin
        count_reg1 <= load_data;
        count_reg2 <= load_data;
    end
end

assign count = count_reg2;

endmodule

