    input clk, 
	 output reg ce1ms=0
    );parameter Fclk = 50000000;
parameter F1kHz = 1000;
reg[15:0]cb_ms = 0;
wire ce = (cb_ms==1);
always @ (posedge clk) begin
cb_ms <=ce?((Fclk/F1kHz)):cb_ms-1;
ce1ms<=ce;
end
endmodule

