module top_module(
    input clock,
    input reset,
    input enable,
    output reg out_data
);parameter WIDTH = 32;
parameter POLYNOMIAL = 32'h04C11DB7;
parameter INITIAL_VALUE = {32{1'b1}};
parameter RESET_VALUE = {32{1'b1}};

reg [WIDTH-1:0] shift_reg;
wire [WIDTH-1:0] polynomial_xor;
wire [WIDTH-1:0] next_data;

assign polynomial_xor = {WIDTH{shift_reg[0]}} & POLYNOMIAL;
assign next_data = ( {1'b1, {shift_reg[WIDTH-1:1]}} ^ polynomial_xor);

always @(posedge clock) begin
    if(reset) begin
        shift_reg <= RESET_VALUE;
    end else if(enable) begin
        shift_reg <= next_data;
    end
end

assign out_data = shift_reg[WIDTH-1];

endmodule

