module top_module(
  input clk,
  input reset,
  output reg [8:0] q,
  output reg enable_tens,
  output reg enable_hundreds
);always @(posedge clk or posedge reset) begin
  if (reset) begin
    q <= 3'b000;
    enable_tens <= 1'b0;
    enable_hundreds <= 1'b0;
  end
  else begin
    if (q[2:0] == 3'b100) begin
      q[2:0] <= 3'b000;
      enable_tens <= 1'b1;
    end
    else begin
      q[2:0] <= q[2:0] + 1;
      enable_tens <= 1'b0;
    end

    if (q[5:3] == 3'b100) begin
      q[5:3] <= 3'b000;
      enable_hundreds <= 1'b1;
    end
    else begin
      q[5:3] <= q[5:3] + 1;
      enable_hundreds <= 1'b0;
    end

    if (q[8:6] == 3'b100) begin
      q[8:6] <= 3'b000;
    end
    else begin
      q[8:6] <= q[8:6] + 1;
    end
  end
end

endmodule

