module state_machine (
        input clk,
        input reset,
        input b,
        output reg y);parameter P=0, Q=1, R=2, S=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= P;
		else 
			state <= next;

	always_comb begin
		case(state)
			P: next = b ? R : Q;
			Q: next = b ? P : S;
			R: next = b ? S : P;
			S: next = b ? R : Q;
			default: next = 'x;
		endcase
	end

	assign y = (state == P || state == Q);

endmodule

