code:
module digital_lock (
	input clk,
	input resetn,
	input [1:0] code,
	output open);

	parameter S0=0, S1=1, S2=2, OPEN=3;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= S0;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			S0: next_state = (code == 2'b01) ? S1 : S0;
			S1: next_state = (code == 2'b10) ? S2 : S0;
			S2: next_state = (code == 2'b01) ? OPEN : S0;
			OPEN: next_state = OPEN;
			default: next_state = S0;
		endcase
	end

	assign open = (state == OPEN);
endmodule

