   function [31:16] get_31_16   ;
      input [31:0] t_crc        ;
      get_31_16 = t_crc[31:16];
   endfunction
`else
   function [31:16] get_31_16;
      input [31:0] t_crc;
      get_31_16 = t_crc[31:16];
   endfunction
`endif

   task set_b_d;
`ifdef ISOLATE
      input [31:0] t_crc        ;
      input [31:0] t_c          ;
`else
      input [31:0] t_crc;
      input [31:0] t_c;
`endif
