         b = {t_crc[31:16],~t_crc[23:8]};
         d = {t_crc[31:16],  ~t_c[23:8]};
      end
   endtask

   always @* begin

      casez (crc[3:0])
        4'b00??: begin
           c = {b[29:0],2'b11};
