module top_module(
  input clk,
  input rst,
  output reg red,
  output reg yellow,
  output reg green
);// Define the states
  parameter STATE_1 = 2'b00;
  parameter STATE_2 = 2'b01;
  parameter STATE_3 = 2'b10;
  parameter STATE_4 = 2'b11;

  // Define the state register and initialize to STATE_1
  reg [1:0] state_reg = STATE_1;

  // Define the state transition logic
  always @(posedge clk, posedge rst) begin
    if (rst) begin
      state_reg <= STATE_1;
    end else begin
      case (state_reg)
        STATE_1: state_reg <= STATE_2;
        STATE_2: state_reg <= STATE_3;
        STATE_3: state_reg <= STATE_4;
        STATE_4: state_reg <= STATE_1;
      endcase
    end
  end

  // Define the output logic based on the current state
  always @(*) begin
    case (state_reg)
      STATE_1: begin
        red <= 0;
        yellow <= 0;
        green <= 1;
      end
      STATE_2: begin
        red <= 0;
        yellow <= 1;
        green <= 0;
      end
      STATE_3: begin
        red <= 1;
        yellow <= 0;
        green <= 0;
      end
      STATE_4: begin
        red <= 1;
        yellow <= 1;
        green <= 0;
      end
    endcase
  end

endmodule

module top_module(
  input clk,
  input reset,
  input [3:0] coin,
  input [3:0] selection,
  output reg dispense,
  output reg [3:0] change
);// Define the states
parameter IDLE = 2'b00;
parameter SELECT = 2'b01;
parameter DISPENSE = 2'b10;

// Define the state register and initialize to IDLE state
reg [1:0] state = IDLE;

// Define the coin and selection registers
reg [3:0] coins_inserted;
reg [3:0] product_selected;

// Define the product prices
parameter [3:0] PRODUCT_A_PRICE = 4;
parameter [3:0] PRODUCT_B_PRICE = 6;

// Define the change register
reg [3:0] change_due;

// Define the state machine
always @(posedge clk, posedge reset) begin
  if (reset) begin
    state <= IDLE;
    coins_inserted <= 4'b0;
    product_selected <= 4'b0;
    dispense <= 1'b0;
    change <= 4'b0;
  end else begin
    case (state)
      IDLE: begin
        if (coin != 4'b0) begin
          coins_inserted <= coins_inserted + coin;
          state <= SELECT;
        end
      end
      SELECT: begin
        if (selection == 4'b0001 && coins_inserted >= PRODUCT_A_PRICE) begin
          product_selected <= selection;
          coins_inserted <= coins_inserted - PRODUCT_A_PRICE;
          state <= DISPENSE;
        end else if (selection == 4'b0010 && coins_inserted >= PRODUCT_B_PRICE) begin
          product_selected <= selection;
          coins_inserted <= coins_inserted - PRODUCT_B_PRICE;
          state <= DISPENSE;
        end else if (selection != 4'b0000) begin
          state <= SELECT;
        end
      end
      DISPENSE: begin
        dispense <= 1'b1;
        change_due <= coins_inserted;
        coins_inserted <= 4'b0;
        product_selected <= 4'b0;
