module top_module(
                clk,
                rst,
                SW2,
                clkdiv,
                Clk_CPU
);input  wire         clk,
                        rst;
    input  wire         SW2;
    output reg  [31: 0]	clkdiv = 0;
    output wire         Clk_CPU;

