   output [0:dest_width-1] data_out;
   wire [0:dest_width-1] data_out;

   genvar 		i;

   generate

      for(i = 0; i < dest_width; i = i + 1)
	begin:bits

	   if((i < offset) || (i >= (offset + data_width)))
	     assign data_out[i] = dest_in[i];
	   else
	     assign data_out[i] = data_in[i - offset];

	end

   endgenerate

endmodule

