module top_module(
	input [31:0] z_postNormaliseSum,
	input [3:0] Opcode_NormaliseSum,
	input idle_NormaliseSum,
	input [31:0] sout_NormaliseSum,
	input [27:0] sum_NormaliseSum,
	input [7:0] InsTagNormaliseAdder,
	input clock,
	output reg [31:0] sout_PackSum,
	output reg Done = 1'b0,
	output reg [31:0] z_postPack,
	output reg [3:0] Opcode_Pack,
	output reg [7:0] InsTagPack
   );parameter no_idle = 1'b0,
			 put_idle = 1'b1;

wire s_sign;
wire [7:0] s_exponent;

assign s_sign = sout_NormaliseSum[31];
assign s_exponent = sout_NormaliseSum[30:23];

parameter sin_cos		= 4'd0,
			 sinh_cosh	= 4'd1,
			 arctan		= 4'd2,
			 arctanh		= 4'd3,
			 exp			= 4'd4,
			 sqr_root   = 4'd5,			

			 division	= 4'd6,
			 tan			= 4'd7,			
			 tanh			= 4'd8,			
			 nat_log		= 4'd9,			
			 hypotenuse = 4'd10,
			 PreProcess = 4'd11;

always @ (posedge clock)
begin

	InsTagPack <= InsTagNormaliseAdder;
	Opcode_Pack <= Opcode_NormaliseSum;
	z_postPack <= z_postNormaliseSum;



	Done <= 1'b0;

	if (idle_NormaliseSum != put_idle) begin
		sout_PackSum[22:0] <= sum_NormaliseSum[25:3];
		sout_PackSum[30:23] <= s_exponent + 127;
		sout_PackSum[31] <= s_sign;
      if ($signed(s_exponent) == -126 && sum_NormaliseSum[22] == 0) begin
         sout_PackSum[30 : 23] <= 0;
      end

		if ($signed(s_exponent) <= -126) begin
			sout_PackSum[30 : 23] <= 0;
			sout_PackSum[22:0] <= 0;
		end


      if ($signed(s_exponent) > 127) begin
         sout_PackSum[22 : 0] <= 0;
         sout_PackSum[30 : 23] <= 255;
         sout_PackSum[31] <= s_sign;
      end		
	end

	else begin
		sout_PackSum <= sout_NormaliseSum;
	end



	if (Opcode_NormaliseSum == sqr_root || Opcode_NormaliseSum == nat_log) begin
		Done <= 1'b1;
	end
end

endmodule

module top_module(
    input clk,
    input rst_n,
    input a,
    input [4:0] in,
    output out_and,
    output out_or,
    output out_nor,
    output reg final_output // Change to reg as it's assigned in an always block
);// Edge detection module
    reg a_prev;
    reg edge_detected;
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            a_prev <= 1'b0;
            edge_detected <= 1'b0;
        end else begin
            a_prev <= a;
            edge_detected <= (a && ~a_prev) || (~a && a_prev);
        end
    end

    // Combinational circuit module
    assign out_and = &in;
    assign out_or = |in;
    assign out_nor = ~|in;

    // Decoder module definition
    reg [3:0] decoder_out; // Change to 4 bits for 2 to 4 decoder output
    always @(*) begin
        case ({1'b1, a_prev}) // Implementing a basic 2 to 4 decoder assuming 'a_prev' is the input
            2'b00: decoder_out = 4'b0001;
            2'b01: decoder_out = 4'b0010;
            2'b10: decoder_out = 4'b0100;
            2'b11: decoder_out = 4'b1000;
            default: decoder_out = 4'b0000;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            final_output <= 1'b0;
        end else begin
            if (edge_detected && (decoder_out[2] || decoder_out[3])) begin // Check bits directly
                final_output <= 1'b1;
            end else begin
                final_output <= 1'b0;
            end
        end
    end

endmodule

